sys_variable_value.value:
(function execute(inputs, outputs) {

    var token_primary = inputs.token;
var payload_primary = inputs.payload;
 
 try { 
 var tokenBearer = token_primary;
 var r = new sn_ws.RESTMessageV2('x_asscs_integra.SAP - ServiceNow', 'terminate');

 r.setEndpoint(getEndpoint() + '/contracts/terminate');
 r.setStringParameterNoEscape('token', tokenBearer);
 r.setRequestHeader('Authorization', 'Bearer ' + tokenBearer);
 r.setRequestHeader('Content-Type', 'application/json');

 var requestBody = payload_primary;
 r.setRequestBody(requestBody);

 gs.info('###Contratos - Distrato ' + requestBody);

 var response = r.execute();
 var responseBody = response.getBody();
 var httpStatus = response.getStatusCode();

 if (httpStatus == 200 || httpStatus == 201 || httpStatus == 202 || httpStatus == 203){
    gs.info('###Contratos - Distrato Sucesso ' + responseBody);

    var responseObject = JSON.parse(responseBody);

    var returnMessages = responseObject.ReturnMessages; // Array de mensagens
    var contractNumber = responseObject.ContractNumber; 
    var returnCode = responseObject.ReturnCode;         
    var companyCode = responseObject.CompanyCode;       

    gs.info('###Contratos ContractNumber: ' + contractNumber);
    gs.info('###Contratos ReturnCode: ' + returnCode);
    gs.info('###Contratos MessageDescription: ' + JSON.stringify(returnMessages));
    gs.info('###Contratos CompanyCode: ' + companyCode);
    outputs.contractnumberanswer = contractNumber;
    outputs.returncode = returnCode;
    outputs.messagedescription = JSON.stringify(returnMessages);
    outputs.companycodeanswer = companyCode;
    
    } else {
    gs.info("###Contratos ResponseBody enviado : " + responseBody); 
    gs.info('###Contratos - Distrato Else ' + httpStatus);
    var responseBodyMessage = JSON.parse(responseBody);

    var mensagens = responseBodyMessage.ReturnMessages.map(function (msg) {
        return msg.Message;
    });

gs.info("Mensagens capturadas: " + JSON.stringify(mensagens).slice(1, -1));
var mensagensCapturadasErro = JSON.stringify(mensagens).slice(1, -1);
outputs.messagetext = mensagensCapturadasErro;
}
    } catch (ex) {
        var message = ex.message;
    }

function getEndpoint() {
    var instanceName = gs.getProperty('instance_name');

    if (instanceName == 'allos') {
        gs.info(gs.getProperty('x_asscs_integra.sap_integramais_endpoint_prd'));
        return gs.getProperty('x_asscs_integra.sap_integramais_endpoint_prd');
    } else {
        gs.info(gs.getProperty('x_asscs_integra.sap_integramais_endpoint_dev_qa'));
        return gs.getProperty('x_asscs_integra.sap_integramais_endpoint_dev_qa');
    }
} 

})(inputs, outputs);

